query_script = """
const path = require('path');
const Database = require('better-sqlite3');
const db = new Database(path.join(__dirname, 'retail.db'));

const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all();
console.log("Tables:", JSON.stringify(tables));

for (const t of tables) {
  const cols = db.prepare(`PRAGMA table_info(${t.name})`).all();
  console.log(`\\nSchema for ${t.name}:`, JSON.stringify(cols.map(c => c.name + ' ' + c.type)));
  const rows = db.prepare(`SELECT * FROM ${t.name} LIMIT 5`).all();
  console.log(`Sample rows:`, JSON.stringify(rows, null, 2));
}
"""
